// Helpers for list views.
export function truncate(text, max) {
  if (text.length <= max) return text;
  if (max <= 0) return '';
  if (max <= 3) return '.'.repeat(max);
  return text.slice(0, max - 3) + '...';
}

export function capitalize(text) {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { truncate, capitalize } from '../src/text.js';

test('short text is left alone', () => assert.equal(truncate('hi', 5), 'hi'));
test('capitalize raises the first letter', () => assert.equal(capitalize('ab'), 'Ab'));
test('long text is cut to max and ends in ...', () => {
  assert.equal(truncate('abcdefgh', 5), 'ab...');
  assert.equal(truncate('abcdefgh', 5).length, 5);
});
test('result never exceeds max', () => {
  for (const max of [0, 1, 2, 3, 4, 10]) {
    assert.ok(truncate('abcdefghijklmnop', max).length <= max, 'max=' + max);
  }
});
test('exact fit is untouched', () => assert.equal(truncate('abcde', 5), 'abcde'));

