import http from 'node:http';
import { truncate } from './src/text.js';

const sample = 'The quick brown fox jumps over the lazy dog';
const rows = [5, 12, 20].map((max) => {
  const result = truncate(sample, max);
  return `<li>truncate(sample, ${max}) = <code>${result}</code> (length ${result.length})</li>`;
});

const server = http.createServer((request, response) => {
  response.writeHead(200, { 'content-type': 'text/html' });
  response.end(`<!doctype html>
<html>
  <head><title>textkit truncate</title></head>
  <body>
    <h1>textkit truncate</h1>
    <p>Sample: <code>${sample}</code></p>
    <ul>${rows.join('')}</ul>
  </body>
</html>`);
});
server.listen(0, () => console.log('Listening on http://localhost:' + server.address().port));
setTimeout(() => { console.log('soak finished'); process.exit(0); }, 7500000);
